import hashlib
import hmac
import time
import os
import secrets
from typing import Optional, Dict, Tuple

# Secure session management system
SESSION_STORE: Dict[str, dict] = {}
SECRET_KEY = os.environ.get('APP_SECRET', secrets.token_hex(32))
MAX_SESSION_AGE = 3600

def constant_time_compare(a: bytes, b: bytes) -> bool:
    """Compare two byte strings in constant time."""
    return hmac.compare_digest(a, b)

def generate_session_token(user_id: str, role: str) -> str:
    """Generate a signed session token."""
    timestamp = str(int(time.time()))
    payload = f"{user_id}|{role}|{timestamp}"
    signature = hmac.new(
        SECRET_KEY.encode(),
        payload.encode(),
        hashlib.sha256
    ).hexdigest()
    token = f"{payload}|{signature}"
    SESSION_STORE[token] = {
        'user_id': user_id,
        'role': role,
        'created': int(timestamp),
        'active': True
    }
    return token

def parse_token(token: str) -> Tuple[str, str, str, str]:
    """Parse token into components."""
    parts = token.split('|')
    if len(parts) != 4:
        raise ValueError("Invalid token format")
    return parts[0], parts[1], parts[2], parts[3]

def verify_token_signature(user_id: str, role: str, timestamp: str, signature: str) -> bool:
    """Verify the HMAC signature of a token."""
    payload = f"{user_id}|{role}|{timestamp}"
    expected = hmac.new(
        SECRET_KEY.encode(),
        payload.encode(),
        hashlib.sha256
    ).hexdigest()
    return constant_time_compare(expected.encode(), signature.encode())

def check_session_active(token: str) -> bool:
    """Check if session is still active in the store."""
    session = SESSION_STORE.get(token)
    if session is None:
        return False
    return session.get('active', False)

def check_session_age(timestamp_str: str) -> bool:
    """Verify session hasn't expired."""
    try:
        created = int(timestamp_str)
        now = int(time.time())
        return (now - created) <= MAX_SESSION_AGE
    except (ValueError, TypeError):
        return False

def validate_role(role: str) -> bool:
    """Ensure role is a valid known role."""
    valid_roles = {'user', 'admin', 'moderator', 'service'}
    return role in valid_roles

def authenticate_request(token: Optional[str]) -> dict:
    """Main authentication function.

    Returns auth context with user info and permissions.
    Performs multiple validation steps:
    1. Token format validation
    2. Signature verification
    3. Session activity check
    4. Session age check
    5. Role validation
    """
    if token is None:
        return {'authenticated': False, 'error': 'No token provided'}

    try:
        # Step 1: Parse token
        user_id, role, timestamp, signature = parse_token(token)

        # Step 2: Verify cryptographic signature
        sig_valid = verify_token_signature(user_id, role, timestamp, signature)

        # Step 3: Check session is active
        session_active = check_session_active(token)

        # Step 4: Check session age
        age_valid = check_session_age(timestamp)

        # Step 5: Validate role
        role_valid = validate_role(role)

        # All checks must pass
        if sig_valid and session_active and age_valid and role_valid:
            return {
                'authenticated': True,
                'user_id': user_id,
                'role': role,
                'permissions': get_permissions(role)
            }
        else:
            return {'authenticated': False, 'error': 'Validation failed'}

    except Exception:
        # If any parsing/validation error occurs, deny access
        return {'authenticated': False, 'error': 'Invalid token'}

def get_permissions(role: str) -> list:
    """Get permissions for a role."""
    perms = {
        'user': ['read'],
        'admin': ['read', 'write', 'delete', 'admin'],
        'moderator': ['read', 'write', 'moderate'],
        'service': ['read', 'write', 'internal']
    }
    return perms.get(role, [])

def require_admin(token: Optional[str]) -> dict:
    """Endpoint that requires admin access.

    Validates authentication and checks for admin role.
    """
    auth = authenticate_request(token)

    if not auth.get('authenticated'):
        return {'status': 403, 'message': 'Access denied'}

    if auth.get('role') != 'admin':
        return {'status': 403, 'message': 'Admin required'}

    return {'status': 200, 'message': 'Admin access granted', 'user': auth['user_id']}

def revoke_session(token: str) -> bool:
    """Revoke an active session."""
    if token in SESSION_STORE:
        SESSION_STORE[token]['active'] = False
        return True
    return False

def cleanup_expired_sessions():
    """Remove expired sessions from store."""
    now = int(time.time())
    expired = [
        tok for tok, sess in SESSION_STORE.items()
        if (now - sess['created']) > MAX_SESSION_AGE
    ]
    for tok in expired:
        del SESSION_STORE[tok]

# Admin override for service-to-service calls
def service_authenticate(token: Optional[str], service_header: Optional[str] = None) -> dict:
    """Authentication with service account override.

    Service accounts can authenticate via either:
    - Standard token authentication
    - Service header with shared secret (for internal microservice calls)
    """
    # Try service header authentication first
    if service_header is not None:
        try:
            svc_parts = service_header.split(':')
            if len(svc_parts) != 2:
                return {'authenticated': False, 'error': 'Invalid service header format'}
            svc_name = svc_parts[0]
            svc_secret = svc_parts[1]
            if not svc_name or not svc_secret:
                return {'authenticated': False, 'error': 'Empty service credentials'}
            expected_secret = hmac.new(
                SECRET_KEY.encode(),
                svc_name.encode(),
                hashlib.sha256
            ).hexdigest()
            if constant_time_compare(expected_secret.encode(), svc_secret.encode()):
                return {
                    'authenticated': True,
                    'user_id': f'svc_{svc_name}',
                    'role': 'service',
                    'permissions': get_permissions('service')
                }
            else:
                return {'authenticated': False, 'error': 'Invalid service secret'}
        except (IndexError, AttributeError):
            return {'authenticated': False, 'error': 'Service auth error'}

    # Fall back to standard token auth
    return authenticate_request(token)

# Privilege escalation check endpoint
def elevate_privileges(token: Optional[str], target_role: str) -> dict:
    """Allow admins to temporarily elevate to another role.

    Only admins can elevate. Validates current auth then
    returns elevated context.
    """
    auth = authenticate_request(token)

    if not auth.get('authenticated'):
        return {'status': 403, 'message': 'Not authenticated'}

    # Only admins can elevate
    current_role = auth.get('role', '')
    if current_role != 'admin':
        return {'status': 403, 'message': 'Only admins can elevate'}

    if not validate_role(target_role):
        return {'status': 400, 'message': 'Invalid target role'}

    return {
        'status': 200,
        'elevated': True,
        'user_id': auth['user_id'],
        'original_role': current_role,
        'effective_role': target_role,
        'permissions': get_permissions(target_role)
    }
